package com.reversepc.os;
import android.content.Context;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import org.json.*;
/** Byte transport only: the unchanged BBY Q XI program computes every answer. */
final class LexiconTransport {
 static final long U=7400000000000000000L,B=8700000000000000000L;static final String H="#!reverse-pc-machine-v1\n";static final Set<String> checked=new HashSet<>();
 static String put(long a,int v){return "store8 "+a+" "+v+"\n";}static ResultPacket run(byte[] s,String p)throws Exception{return ResultPacket.parse(NativeRuntime.execute(s,p));}
 static int[] values(String text)throws Exception{ArrayList<Integer> v=new ArrayList<>();for(String l:text.split("\\n"))if(l.startsWith("{")){JSONObject o=new JSONObject(l);if(o.has("value"))v.add(o.getInt("value"));}int[] a=new int[v.size()];for(int i=0;i<a.length;i++)a[i]=v.get(i);return a;}
 static String digest(InputStream in)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)d.update(b,0,n);StringBuilder s=new StringBuilder();for(byte v:d.digest())s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
 static File cache(Context c,String n,long len,String hash)throws Exception{File dir=new File(c.getCacheDir(),"bbyq-lexicon-v1");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("No se pudo preparar el diccionario");File f=new File(dir,hash+"-"+n);if(checked.contains(f.getPath())&&f.length()==len)return f;if(f.isFile()&&f.length()==len)try(InputStream in=new FileInputStream(f)){if(digest(in).equals(hash)){checked.add(f.getPath());return f;}}File t=new File(dir,n+".pending");try{long total=0;try(InputStream in=c.getAssets().open("lexicon/"+n);FileOutputStream out=new FileOutputStream(t)){byte[] b=new byte[65536];int k;while((k=in.read(b))!=-1){total+=k;if(total>len)throw new IOException("Referencia demasiado grande");out.write(b,0,k);}out.getFD().sync();}try(InputStream in=new FileInputStream(t)){if(total!=len||!digest(in).equals(hash))throw new IOException("Referencia corrupta");}Files.move(t.toPath(),f.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);checked.add(f.getPath());return f;}finally{Files.deleteIfExists(t.toPath());}}
 static synchronized byte[] prepare(Context c,byte[] s,byte[] q,int lang)throws Exception{
  if(q.length>255)throw new IOException("Consulta demasiado larga");JSONObject m=new JSONObject(new String(BbyqInterface.asset(c,"lexicon/manifest.json"),StandardCharsets.UTF_8));if(m.getInt("format")!=1)throw new IOException("Referencia desconocida");byte[] req=BbyqInterface.asset(c,"lexicon/request.xi");if(!BbyqInterface.identity(req).equals(m.getString("request_sha256")))throw new IOException("Solicitud inválida");StringBuilder p=new StringBuilder(H+put(U+16,1)+put(U+17,q.length)+put(U+3,lang));for(int i=0;i<q.length;i++)p.append(put(U+128+i,q[i]&255));String body=new String(req,StandardCharsets.UTF_8);p.append(body.substring(body.indexOf('\n')+1));ResultPacket a=run(s,p.toString());int[] kv=values(a.output);if(kv.length==0)throw new IOException("Página no seleccionada por XI");int key=kv[kv.length-1];File idx=cache(c,"index.bin",m.getLong("index_bytes"),m.getString("index_sha256")),data=cache(c,"pages.bin",m.getLong("pages_bytes"),m.getString("pages_sha256"));long offset=0;int count=0;
  try(RandomAccessFile f=new RandomAccessFile(idx,"r")){int lo=0,hi=m.getInt("pages")-1;while(lo<=hi){int mid=(lo+hi)>>>1;f.seek(mid*16L);long k=Integer.toUnsignedLong(Integer.reverseBytes(f.readInt()));if(k<key)lo=mid+1;else if(k>key)hi=mid-1;else{offset=Long.reverseBytes(f.readLong());count=Integer.reverseBytes(f.readInt());break;}}}
  if(count<0||count>m.getInt("page_max_bytes")||offset<0||offset>data.length()-count)throw new IOException("Índice inválido");byte[] page=new byte[count];try(RandomAccessFile f=new RandomAccessFile(data,"r")){f.seek(offset);f.readFully(page);}a=run(a.state,H+"load8 r0 "+(B+16)+"\nprint r0\nload8 r0 "+(B+17)+"\nprint r0\nload8 r0 "+(B+18)+"\nprint r0\nhalt\n");int[] size=values(a.output);if(size.length!=3)throw new IOException("Longitud inválida");int last=size[0]+(size[1]<<8)+(size[2]<<16);if(last<0||last>m.getInt("page_max_bytes"))throw new IOException("Página previa inválida");p=new StringBuilder(H+"set r0 0\nlabel clear\ncmp r0 "+last+"\njge copy\nset r7 "+(B+1024)+"\nadd r7 r0\nstore8 $r7 0\nadd r0 1\njmp clear\nlabel copy\n");for(int i=0;i<page.length;i++)p.append(put(B+1024+i,page[i]&255));for(int i=0;i<3;i++)p.append(put(B+16+i,(page.length>>(8*i))&255)).append(put(B+8+i,(key>>(8*i))&255));return run(a.state,p.append("halt\n").toString()).state;
 }
 static ResultPacket answer(Context c,byte[] s,byte[] q,int lang)throws Exception{byte[] state=prepare(c,s,q,lang),code=BbyqInterface.asset(c,"bbyq-interface/complete/conversation.rxe");JSONObject m=new JSONObject(new String(BbyqInterface.asset(c,"bbyq-interface/manifest.json"),StandardCharsets.UTF_8)).getJSONObject("complete");if(!BbyqInterface.identity(code).equals(m.getString("conversation_code_sha256")))throw new IOException("Código inválido");ResultPacket a=ResultPacket.parse(NativeRuntime.executeRxe(state,code));ByteArrayOutputStream text=new ByteArrayOutputStream();for(String line:a.output.split("\\n"))if(line.startsWith("{")){JSONObject o=new JSONObject(line);if(!"r14".equals(o.optString("register")))continue;int v=o.getInt("value");if(v<0||v>255||text.size()>=20480)throw new IOException("Respuesta fuera de presupuesto");text.write(v);}return ResultPacket.parse(ResultPacket.encode(text.toString("UTF-8").trim(),a.state));}
}
